exercises.solution:
const STOCK = { riz: { nom: "Riz", prix: 600 }, huile: { nom: "Huile", prix: 1500 } };

function chercherProduit(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (STOCK[id]) resolve(STOCK[id]);
      else reject(new Error("produit introuvable : " + id));
    }, 2);
  });
}

async function chargerTout(ids) {
  const resultats = await Promise.allSettled(ids.map(chercherProduit));
  const noms = resultats.filter(r => r.status === "fulfilled").map(r => r.value.nom);
  return { noms, erreurs: resultats.length - noms.length };
}
